const GENRES = ["Action", "Comedy", "Horror", "Sci-Fi", "Drama", "Romance", "Thriller", "Animation"];

const GRAD = {
  Action: ["#3A0A0A", "#7A1414"],
  Comedy: ["#3A2E00", "#7A5E00"],
  Horror: ["#150014", "#3D0A38"],
  "Sci-Fi": ["#001A2E", "#0A3D66"],
  Drama: ["#1A0E24", "#402159"],
  Romance: ["#2E0018", "#6B0A3E"],
  Thriller: ["#0E1414", "#1F3A3A"],
  Animation: ["#012A1E", "#0A5C3E"],
};

function formatMovie(m) {
  if (!m) return m;
  const genre = m.genres?.[0] || "Action";
  return {
    ...m,
    desc: m.description || m.desc || "",
    posterUrl: m.poster_url || m.posterUrl || POSTER_MAP[m.title] || ADDITIONAL_POSTERS[m.title] || null,
    isKidSafe: m.is_kid_safe ?? m.isKidSafe ?? false,
    grad: GRAD[genre] || GRAD["Action"],
  };
}

/* ---------------- components ---------------- */
function RatingBadge({ v }) {
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 3,
      background: "rgba(242, 179, 0, 0.15)", color: T.amber,
      border: `1px solid ${T.amberDim}`, borderRadius: 4,
      padding: "1px 6px", fontSize: 11, fontWeight: 700,
    }}>
      <Star size={11} fill={T.amber} /> {v}
    </span>
  );
}

function Toast({ msg }) {
  if (!msg) return null;
  return (
    <div style={{
      position: "fixed", bottom: 24, right: 24, zIndex: 999,
      background: T.surface2, color: T.text, border: `1px solid ${T.line}`,
      borderRadius: 8, padding: "10px 16px", boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
      fontSize: 13, display: "flex", alignItems: "center", gap: 8,
    }}>
      <Check size={15} color={T.teal} /> {msg}
    </div>
  );
}

function MovieCard({ m, inList, onAdd, onOpen, progress }) {
  const [hover, setHover] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [c1, c2] = m.grad || ["#1E1B22", "#3A0A0A"];
  return (
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onClick={() => onOpen(m.id)}
      style={{
        flexShrink: 0, width: 180, height: 260, borderRadius: 8, position: "relative",
        cursor: "pointer", overflow: "hidden", border: `1px solid ${T.line}`,
        transition: "transform 0.25s ease, box-shadow 0.25s ease",
        transform: hover ? "scale(1.05)" : "scale(1)",
        zIndex: hover ? 20 : 1,
        boxShadow: hover ? "0 12px 28px rgba(0,0,0,0.8)" : "none",
        background: `linear-gradient(135deg, ${c1}, ${c2})`,
      }}
    >
      {m.posterUrl && !imgError ? (
        <img 
          src={m.posterUrl} 
          alt={m.title} 
          onError={() => setImgError(true)} 
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} 
        />
      ) : (
        <div style={{ padding: 14, height: "100%", display: "flex", flexDirection: "column", justifyContent: "space-between", boxSizing: "border-box" }}>
          <div>
            <span style={{ fontSize: 10, letterSpacing: 1, textTransform: "uppercase", color: T.amber, fontWeight: 700 }}>
              {m.type === "tv" ? "TV Series" : "Movie"}
            </span>
            <div style={{ fontFamily: "Georgia, serif", fontSize: 17, fontWeight: 700, color: "#fff", marginTop: 6, lineHeight: 1.25 }}>
              {m.title}
            </div>
          </div>
          <div>
            <div style={{ fontSize: 11, color: T.amber, marginBottom: 4, fontWeight: 700 }}>★ {m.rating}</div>
            <div style={{ fontSize: 11, color: T.mute }}>{m.genres?.join(" · ")}</div>
          </div>
        </div>
      )}

      {progress !== undefined && progress > 0 && (
        <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: 3, background: "rgba(255,255,255,0.2)" }}>
          <div style={{ height: "100%", width: `${progress}%`, background: T.red }} />
        </div>
      )}

      <div style={{
        position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(10,10,13,0.95) 10%, transparent 60%)",
        opacity: hover ? 1 : 0, transition: "opacity 0.2s ease", padding: 12, display: "flex", flexDirection: "column", justifyContent: "flex-end",
      }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: "#fff" }}>{m.title}</div>
        <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 6 }}>
          <button
            onClick={(e) => { e.stopPropagation(); onOpen(m.id, true); }}
            style={{ background: "#fff", border: "none", borderRadius: "50%", width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
          ><Play size={14} fill="#111" color="#111" /></button>
          <button
            onClick={(e) => { e.stopPropagation(); onAdd(m.id); }}
            style={{ background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.3)", borderRadius: "50%", width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: "#fff" }}
          >{inList ? <Check size={14} /> : <Plus size={14} />}</button>
        </div>
        <div style={{ fontSize: 11, color: T.mute, marginTop: 6, display: "flex", gap: 6, alignItems: "center" }}>
          <RatingBadge v={m.rating} /> <span>{m.year}</span>
        </div>
      </div>
    </div>
  );
}

function MovieRow({ title, items, myList, onAdd, onOpen, progressMap }) {
  const ref = useRef(null);
  const scroll = (dir) => ref.current?.scrollBy({ left: dir * 620, behavior: "smooth" });
  if (!items || !items.length) return null;
  return (
    <div style={{ marginBottom: 30, position: "relative" }}>
      <h3 style={{ fontSize: 17, fontWeight: 700, margin: "0 0 10px 4px", letterSpacing: 0.3 }}>{title}</h3>
      <div style={{ position: "relative" }}>
        <button aria-label="Scroll left" onClick={() => scroll(-1)} style={navBtnStyle("left")}><ChevronLeft size={20} /></button>
        <div ref={ref} style={{ display: "flex", gap: 10, overflowX: "auto", scrollbarWidth: "none", paddingBottom: 4 }}>
          {items.map((m) => (
            <MovieCard key={m.id} m={m} inList={myList.has(m.id)} onAdd={onAdd} onOpen={onOpen} progress={progressMap[m.id]} />
          ))}
        </div>
        <button aria-label="Scroll right" onClick={() => scroll(1)} style={navBtnStyle("right")}><ChevronRight size={20} /></button>
      </div>
    </div>
  );
}

function navBtnStyle(side) {
  return {
    position: "absolute", [side]: -6, top: 0, bottom: 0, width: 34, zIndex: 10,
    background: `linear-gradient(to ${side === "left" ? "right" : "left"}, rgba(10,10,13,0.9), transparent)`,
    border: "none", color: "#fff", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: side === "left" ? "flex-start" : "flex-end",
  };
}

function Navbar({ view, setView, user, kidsMode, setKidsMode, query, setQuery, onSearchSubmit, activeProfile }) {
  const [menu, setMenu] = useState(false);
  const links = [
    { id: "home", label: "Home" },
    { id: "movies", label: "Movies" },
    { id: "tv", label: "TV Shows" },
    { id: "mylist", label: "My List" },
  ];
  return (
    <div style={{
      position: "sticky", top: 0, zIndex: 100, display: "flex", alignItems: "center",
      justifyContent: "space-between", padding: "14px 40px", background: "linear-gradient(to bottom, rgba(10,10,13,0.95), transparent)",
      backdropFilter: "blur(4px)",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 30 }}>
        <div onClick={() => setView("home")} style={{ cursor: "pointer", fontFamily: "Georgia, serif", fontWeight: 900, fontSize: 26, letterSpacing: 1, color: T.red }}>
          NETFLIX
        </div>
        <div style={{ display: "flex", gap: 20 }}>
          {links.map((l) => (
            <button key={l.id} onClick={() => setView(l.id)}
              style={{ background: "none", border: "none", cursor: "pointer", fontSize: 14, padding: 0,
                color: view === l.id ? T.text : T.mute, fontWeight: view === l.id ? 700 : 400 }}>
              {l.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
        <div style={{ display: "flex", alignItems: "center", background: view === "search" ? T.surface2 : "transparent", border: `1px solid ${view === "search" ? T.line : "transparent"}`, borderRadius: 6, padding: "4px 8px" }}>
          <Search size={15} color={T.mute} />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onFocus={() => setView("search")}
            onKeyDown={(e) => e.key === "Enter" && onSearchSubmit()}
            placeholder="Titles, genres..."
            aria-label="Search titles"
            style={{ background: "transparent", border: "none", outline: "none", color: T.text, fontSize: 13, marginLeft: 6, width: 140 }}
          />
        </div>
        {kidsMode && <span style={{ fontSize: 11, color: T.teal, border: `1px solid ${T.teal}`, borderRadius: 4, padding: "2px 6px" }}>KIDS</span>}
        <div style={{ position: "relative" }}>
          <button onClick={() => setMenu((v) => !v)} aria-label="Profile menu" style={{
            width: 32, height: 32, borderRadius: 6, border: "none", cursor: "pointer",
            background: `linear-gradient(135deg, ${T.red}, #7A0A0F)`, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff",
          }}><User size={16} /></button>
          {menu && (
            <div style={{ position: "absolute", right: 0, top: 38, background: T.surface2, border: `1px solid ${T.line}`, borderRadius: 8, width: 190, padding: 6, boxShadow: "0 10px 30px rgba(0,0,0,0.5)" }}>
              {user ? (
                <>
                  <MenuItem icon={<User size={14} />} label={`Profile (${activeProfile?.name || "Primary"})`} onClick={() => { setView("profile"); setMenu(false); }} />
                  <MenuItem icon={<Baby size={14} />} label={kidsMode ? "Exit Kids Mode" : "Kids Mode"} onClick={() => { setKidsMode((v) => !v); setMenu(false); }} />
                  <MenuItem icon={<LogOut size={14} />} label="Sign Out" onClick={() => { localStorage.removeItem("token"); window.location.reload(); }} />
                </>
              ) : (
                <MenuItem icon={<User size={14} />} label="Sign In" onClick={() => { setView("login"); setMenu(false); }} />
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function MenuItem({ icon, label, onClick }) {
  return (
    <button onClick={onClick} style={{ display: "flex", alignItems: "center", gap: 8, width: "100%", background: "none", border: "none", color: T.text, fontSize: 13, padding: "8px 10px", borderRadius: 6, cursor: "pointer", textAlign: "left" }}
      onMouseEnter={(e) => e.currentTarget.style.background = T.surface}
      onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}
    >{icon}{label}</button>
  );
}

function Hero({ movies = [], onPlay, onInfo }) {
  const featured = useMemo(() => {
    if (!movies || !movies.length) return [];
    return movies.slice(0, 6);
  }, [movies]);

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  useEffect(() => {
    if (!featured.length || isPaused) return;
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % featured.length);
    }, 5000);
    return () => clearInterval(interval);
  }, [featured.length, isPaused]);

  if (!featured.length) return null;

  const movie = featured[currentIndex] || featured[0];
  const [c1, c2] = movie.grad || ["#0A0A0D", "#3A0A0A"];

  return (
    <div
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      style={{
        position: "relative",
        height: "65vh",
        minHeight: 440,
        overflow: "hidden",
        background: `radial-gradient(circle at 75% 30%, ${c2}, ${c1} 60%, #0A0A0D 100%)`,
        display: "flex",
        alignItems: "flex-end",
      }}
    >
      {movie.posterUrl && (
        <div
          key={movie.id}
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage: `url(${movie.posterUrl})`,
            backgroundSize: "cover",
            backgroundPosition: "center 20%",
            opacity: 0.35,
            filter: "brightness(0.85)",
            transition: "opacity 0.8s ease-in-out",
          }}
        />
      )}

      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "linear-gradient(to top, #0A0A0D 4%, transparent 50%), linear-gradient(to right, rgba(10,10,13,0.95) 25%, rgba(10,10,13,0.6) 60%, transparent 100%)",
        }}
      />

      <div
        key={`content-${movie.id}`}
        style={{
          position: "relative",
          padding: "0 44px 56px",
          maxWidth: 620,
          zIndex: 2,
        }}
      >
        <div style={{ fontSize: 12, letterSpacing: 2, color: T.amber, textTransform: "uppercase", marginBottom: 10, fontWeight: 700 }}>
          Featured {movie.type === "tv" ? "Series" : "Film"} · {currentIndex + 1} of {featured.length}
        </div>
        <h1 style={{ fontFamily: "Georgia, serif", fontSize: 48, fontWeight: 800, lineHeight: 1.05, margin: 0, color: "#fff", textShadow: "0 4px 12px rgba(0,0,0,0.6)" }}>
          {movie.title}
        </h1>
        <div style={{ display: "flex", gap: 12, alignItems: "center", marginTop: 14, fontSize: 13, color: T.mute }}>
          <RatingBadge v={movie.rating} /> <span>{movie.year}</span> <span>{movie.duration}</span> <span>{movie.genres?.join(" · ")}</span>
        </div>
        <p style={{ color: "#DAD5D0", fontSize: 14, lineHeight: 1.5, marginTop: 14, textShadow: "0 2px 4px rgba(0,0,0,0.8)" }}>
          {movie.desc}
        </p>
        <div style={{ display: "flex", gap: 12, marginTop: 22 }}>
          <button
            onClick={() => onPlay(movie.id)}
            style={{ display: "flex", alignItems: "center", gap: 8, background: "#fff", color: "#111", border: "none", borderRadius: 6, padding: "10px 24px", fontWeight: 700, fontSize: 14, cursor: "pointer", boxShadow: "0 4px 15px rgba(255,255,255,0.2)" }}
          >
            <Play size={16} fill="#111" /> Play
          </button>
          <button
            onClick={() => onInfo(movie.id)}
            style={{ display: "flex", alignItems: "center", gap: 8, background: "rgba(255,255,255,0.2)", color: "#fff", border: "none", borderRadius: 6, padding: "10px 24px", fontWeight: 700, fontSize: 14, cursor: "pointer", backdropFilter: "blur(4px)" }}
          >
            <Info size={16} /> More Info
          </button>
        </div>
      </div>

      <button
        onClick={() => setCurrentIndex((prev) => (prev - 1 + featured.length) % featured.length)}
        aria-label="Previous Featured Movie"
        style={{
          position: "absolute",
          left: 10,
          top: "45%",
          zIndex: 10,
          background: "rgba(0,0,0,0.4)",
          border: "none",
          borderRadius: "50%",
          width: 40,
          height: 40,
          color: "#fff",
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <ChevronLeft size={24} />
      </button>

      <button
        onClick={() => setCurrentIndex((prev) => (prev + 1) % featured.length)}
        aria-label="Next Featured Movie"
        style={{
          position: "absolute",
          right: 10,
          top: "45%",
          zIndex: 10,
          background: "rgba(0,0,0,0.4)",
          border: "none",
          borderRadius: "50%",
          width: 40,
          height: 40,
          color: "#fff",
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <ChevronRight size={24} />
      </button>

      <div style={{ position: "absolute", right: 44, bottom: 24, zIndex: 10, display: "flex", gap: 8, alignItems: "center" }}>
        {featured.map((m, idx) => (
          <button
            key={m.id}
            onClick={() => setCurrentIndex(idx)}
            title={m.title}
            style={{
              width: currentIndex === idx ? 24 : 8,
              height: 8,
              borderRadius: 4,
              border: "none",
              background: currentIndex === idx ? T.red : "rgba(255,255,255,0.4)",
              cursor: "pointer",
              transition: "all 0.3s ease",
            }}
          />
        ))}
      </div>
    </div>
  );
}

