            <button onClick={() => onAdd(movie.id)} style={{ display: "flex", alignItems: "center", gap: 8, background: T.surface2, color: "#fff", border: `1px solid ${T.line}`, borderRadius: 6, padding: "10px 22px", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>
              {myList.has(movie.id) ? <Check size={16} /> : <Plus size={16} />} {myList.has(movie.id) ? "In My List" : "My List"}
            </button>
