function Watch({ movie, onBack, onProgress, initialProgress }) {
  const [playing, setPlaying] = useState(true);
  const [pct, setPct] = useState(initialProgress || 0);
  const timerRef = useRef(null);

  useEffect(() => {
    timerRef.current = setInterval(() => {
      setPct((p) => {
        const next = Math.min(100, p + 0.5);
        onProgress(movie.id, next);
        if (next >= 100) clearInterval(timerRef.current);
        return next;
      });
    }, 300);
    return () => clearInterval(timerRef.current);
  }, [movie.id, onProgress]);

  return (
    <div style={{ position: "fixed", inset: 0, background: "#000", zIndex: 1000, display: "flex", flexDirection: "column", justifyContent: "space-between", padding: 24 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <button onClick={onBack} style={{ background: "rgba(255,255,255,0.2)", border: "none", borderRadius: "50%", width: 40, height: 40, color: "#fff", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><ArrowLeft size={20} /></button>
        <div style={{ color: "#fff", fontSize: 16, fontWeight: 700 }}>Now Playing: {movie.title}</div>
        <div style={{ width: 40 }} />
      </div>
      <div style={{ textAlign: "center", color: T.mute }}>
        <Film size={64} style={{ marginBottom: 16, opacity: 0.4 }} />
        <div style={{ fontSize: 18, color: "#fff" }}>Simulated Playback Engine</div>
        <div style={{ fontSize: 13, marginTop: 6 }}>Resume progress saved automatically to database</div>
      </div>
      <div>
        <div style={{ height: 4, background: "rgba(255,255,255,0.2)", borderRadius: 2, overflow: "hidden", marginBottom: 12 }}>
          <div style={{ height: "100%", width: `${pct}%`, background: T.red, transition: "width 0.3s linear" }} />
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", color: T.mute, fontSize: 12 }}>
          <span>{Math.floor(pct)}% completed</span>
          <span>{movie.duration || "1h 45m"}</span>
        </div>
      </div>
    </div>
  );
}

