function Login({ onSignIn, goSignup, goHome }) {
  const [email, setEmail] = useState("demo@example.com");
  const [pw, setPw] = useState("password123");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE}/auth/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password: pw }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Login failed");
      localStorage.setItem("token", data.token);
      onSignIn(data.user, data.profiles);
    } catch (e) {
      setErr(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <AuthShell goHome={goHome}>
      <h2 style={{ fontSize: 20, margin: "0 0 18px" }}>Sign In to Netflix API</h2>
      <form onSubmit={submit}>
        <Field label="Email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <Field label="Password" type="password" value={pw} onChange={(e) => setPw(e.target.value)} />
        {err && <div style={{ color: "#FF6B6B", fontSize: 12, marginBottom: 12 }}>{err}</div>}
        <button type="submit" disabled={loading} style={{ width: "100%", background: T.red, color: "#fff", border: "none", borderRadius: 6, padding: "11px 0", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 4 }}>
          {loading ? "Connecting..." : "Sign In"}
        </button>
      </form>
      <div style={{ textAlign: "center", marginTop: 16, fontSize: 12, color: T.mute }}>
        Need an account? <button onClick={goSignup} style={{ background: "none", border: "none", color: T.red, cursor: "pointer", padding: 0 }}>Create account</button>
      </div>
    </AuthShell>
  );
}

function Signup({ onSignUp, goLogin, goHome }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE}/auth/signup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, password: pw }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Signup failed");
      localStorage.setItem("token", data.token);
      onSignUp(data.user, data.profiles);
    } catch (e) {
      setErr(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <AuthShell goHome={goHome}>
      <h2 style={{ fontSize: 20, margin: "0 0 18px" }}>Create Account</h2>
      <form onSubmit={submit}>
        <Field label="Name" value={name} onChange={(e) => setName(e.target.value)} />
        <Field label="Email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <Field label="Password" type="password" value={pw} onChange={(e) => setPw(e.target.value)} />
        {err && <div style={{ color: "#FF6B6B", fontSize: 12, marginBottom: 12 }}>{err}</div>}
        <button type="submit" disabled={loading} style={{ width: "100%", background: T.red, color: "#fff", border: "none", borderRadius: 6, padding: "11px 0", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 4 }}>
          {loading ? "Creating..." : "Sign Up"}
        </button>
      </form>
      <div style={{ textAlign: "center", marginTop: 16, fontSize: 12, color: T.mute }}>
        Already have an account? <button onClick={goLogin} style={{ background: "none", border: "none", color: T.red, cursor: "pointer", padding: 0 }}>Sign in</button>
      </div>
    </AuthShell>
  );
}

