function NetflixIntro({ onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2200);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div onClick={onDone} style={{ position: "fixed", inset: 0, background: "#000", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
      <div style={{ fontFamily: "Georgia, serif", fontWeight: 900, fontSize: "8vw", color: T.red, letterSpacing: 2 }}>
        NETFLIX
      </div>
    </div>
  );
}

